const repairBalance = `-- name: RepairBalance :exec
INSERT INTO stock_balance (tenant_id, outlet_id, stock_item_id, quantity_scaled, value, cost_quantity, cost_value, seq)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
ON CONFLICT (tenant_id, outlet_id, stock_item_id) DO UPDATE
SET quantity_scaled = excluded.quantity_scaled, value = excluded.value, cost_quantity = excluded.cost_quantity,
    cost_value = excluded.cost_value, seq = excluded.seq, updated_at = now()
`

type RepairBalanceParams struct {
	TenantID       uuid.UUID
	OutletID       uuid.UUID
	StockItemID    uuid.UUID
	QuantityScaled int64
	Value          int64
	CostQuantity   *int64
	CostValue      *int64
	Seq            int64
}

// Sets a balance to what the ledger says (BR-STK-08). The ledger itself is never changed.
func (q *Queries) RepairBalance(ctx context.Context, arg RepairBalanceParams) error {
	_, err := q.db.Exec(ctx, repairBalance,
		arg.TenantID,
		arg.OutletID,
		arg.StockItemID,
		arg.QuantityScaled,
		arg.Value,
		arg.CostQuantity,
		arg.CostValue,
		arg.Seq,
	)
	return err
}

const seedStandardUnits = `-- name: SeedStandardUnits :exec

SELECT seed_standard_units($1::uuid)
`

// UoM categories and units
func (q *Queries) SeedStandardUnits(ctx context.Context, tenantID uuid.UUID) error {
	_, err := q.db.Exec(ctx, seedStandardUnits, tenantID)
	return err
}

const unitsUsedByItems = `-- name: UnitsUsedByItems :many
SELECT DISTINCT u.id FROM uom u
WHERE u.tenant_id = $1 AND u.id = ANY($2::uuid[])
  AND EXISTS (SELECT 1 FROM stock_item i WHERE i.tenant_id = u.tenant_id AND (i.base_uom_id = u.id OR i.recipe_uom_id = u.id))
`

type UnitsUsedByItemsParams struct {
	TenantID uuid.UUID
	Ids      []uuid.UUID
}

// Which of these units an item uses as its base or recipe unit (BR-UOM-07).
func (q *Queries) UnitsUsedByItems(ctx context.Context, arg UnitsUsedByItemsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, unitsUsedByItems, arg.TenantID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

